SINA_SMART["bacterio1-bordetella"] = {"lecture":"bacterio1-bordetella","title":"Bordetella pertussis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-bordetella:e0","text":"Strictly human, highly contagious, droplets; colonises ciliated epithelium.","topic":"The organism","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e1","text":"Small Gram-negative coccobacillus; strict aerobe; fastidious, asaccharolytic.","topic":"The organism","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e2","text":"Adhesins: FHA, fimbriae, pertactin.","topic":"Virulence factors and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e3","text":"Toxins: pertussis toxin (lymphocytosis), tracheal cytotoxin (ciliostasis), adenylate cyclase toxin.","topic":"Virulence factors and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e4","text":"Stages: catarrhal (most contagious), paroxysmal (whoop, vomiting, apnoea), convalescent.","topic":"Clinical stages","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e5","text":"Posterior nasopharyngeal swab; PCR first line (IS481, ptxP).","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e6","text":"Culture: Regan-Lowe or Bordet-Gengou, no CO₂, 7-10 days, mercury-drop colonies.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e7","text":"Serology only retrospective.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e8","text":"Macrolides (azithromycin) first; TMP-SMX alternative.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-bordetella:e9","text":"Morocco: whole-cell DTP (pentavalent) at 2, 3, 4 months; boosters 18 months and 5 years.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1cnyx6m":"a","1pf9ex9":"a","by2sla":"a","3qeaqf":"a","qhq2hq":"a","814cb6":"a","14a5d4":"a","1k8f201":"a","1quys3e":"a","l7c1y4":"a","ox11yk":"a","1aabnic":"a","1yoy7nd":"a","102fl6o":"a","1k9hkg7":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-bordetella:e0":{"s":0,"u":["Strictly human, highly contagious, droplets; colonises ciliated epithelium.","B. pertussis is a strictly human , highly contagious pathogen spread by droplets , colonising the ciliated epithelium of the nasopharynx, trachea and bronchi."],"dp":[]},"bacterio1-bordetella:e1":{"s":0,"u":["Small Gram-negative coccobacillus; strict aerobe; fastidious, asaccharolytic.","It is a small Gram-negative coccobacillus (0.2-0.5 × 0.5-2 µm), single or in pairs, no true capsule, non-motile , strictly aerobic , oxidase and catalase positive, asaccharolytic , and fastidious : it needs charcoal- or blood-based media and forms pinpoint colonies after 3-6 days or more."],"dp":[]},"bacterio1-bordetella:e2":{"s":1,"u":["Adhesins: FHA, fimbriae, pertactin.","Adhesins : filamentous haemagglutinin (FHA) , fimbriae (FIM2, FIM3), pertactin and tracheal colonisation factor."],"dp":[]},"bacterio1-bordetella:e3":{"s":1,"u":["Toxins: pertussis toxin (lymphocytosis), tracheal cytotoxin (ciliostasis), adenylate cyclase toxin.","Toxins : pertussis toxin (PT) , a protein exotoxin (causes lymphocytosis, raises insulin secretion, blunts immune cells), tracheal cytotoxin (ciliostasis and death of ciliated cells), adenylate cyclase toxin (paralyses phagocytes), dermonecrotic toxin and LPS/LOS endotoxin."],"dp":[]},"bacterio1-bordetella:e4":{"s":2,"u":["Stages: catarrhal (most contagious), paroxysmal (whoop, vomiting, apnoea), convalescent.","Paroxysmal (2-6 weeks or longer): bursts of rapid coughing from thick mucus, an inspiratory whoop , post-tussive vomiting , exhaustion, up to about 15 attacks a day, worse at night; apnoea in infants , who are at greatest risk.","Catarrhal (1-2 weeks): coryza, low fever, mild cough; most contagious and hard to tell from a cold."],"dp":[{"h":"Why antibiotics barely change the cough","t":"By the time the typical whoop appears, the bacteria have already paralysed and destroyed ciliated cells and released toxins; many patients have cleared most bacteria by then. Antibiotics started in the paroxysmal stage therefore do little to shorten the cough, which lasts until the ciliated lining regenerates, but they still matter: they stop the patient spreading the infection to unvaccinated infants, in whom pertussis can cause apnoea and death. That is also why contacts are treated and pregnant women are offered a booster, so that antibodies cross the placenta. Source: the lecture's clinical stages and treatment notes."}]},"bacterio1-bordetella:e5":{"s":3,"u":["Posterior nasopharyngeal swab; PCR first line (IS481, ptxP).","PCR is first line : faster, more sensitive (especially early) and positive after antibiotics; targets IS481 (sensitive but not fully specific) and the pertussis toxin promoter (ptxP) (more specific).","Specimen : posterior nasopharyngeal swab (Dacron or flocked) or aspirate, not the anterior nostril, placed at once in transport medium (Amies with charcoal, Regan-Lowe)."],"dp":[]},"bacterio1-bordetella:e6":{"s":3,"u":["Culture: Regan-Lowe or Bordet-Gengou, no CO₂, 7-10 days, mercury-drop colonies.","Culture is the gold standard but insensitive: Regan-Lowe agar (charcoal, horse blood, cephalexin; reference medium) or Bordet-Gengou (potato, glycerol, blood), 35-37 °C, humid, no CO₂ , 7-10 days ; small shiny ' mercury drop ' colonies."],"dp":[]},"bacterio1-bordetella:e7":{"s":3,"u":["Serology only retrospective.","Serology (ELISA IgG/IgA against PT) is only retrospective and hard to interpret within a year of vaccination."],"dp":[]},"bacterio1-bordetella:e8":{"s":4,"u":["Macrolides (azithromycin) first; TMP-SMX alternative.","Macrolides are first line: azithromycin , erythromycin or clarithromycin; they are most effective early and reduce transmission even when the cough persists.","Trimethoprim-sulfamethoxazole is the alternative (intolerance, or suspected macrolide resistance, which is rare and not a major issue in Morocco)."],"dp":[]},"bacterio1-bordetella:e9":{"s":4,"u":["Morocco: whole-cell DTP (pentavalent) at 2, 3, 4 months; boosters 18 months and 5 years.","Vaccination in Morocco : a whole-cell pertussis vaccine combined as DTP, usually the pentavalent DTP-HepB-Hib, at 2, 3 and 4 months , with boosters at 18 months and 5 years ."],"dp":[]}},"meta":{"1cnyx6m":{"a":"recall","vg":"bacterio1-bordetella:e1/recall/1"},"1pf9ex9":{"a":"recall","vg":"bacterio1-bordetella:e0/recall/1"},"by2sla":{"a":"recall","vg":"bacterio1-bordetella:e4/recall/1"},"3qeaqf":{"a":"recall","vg":"bacterio1-bordetella:e4/recall/1"},"qhq2hq":{"a":"recall","vg":"bacterio1-bordetella:e3/recall/1"},"814cb6":{"a":"recall","vg":"bacterio1-bordetella:e3/recall/2"},"14a5d4":{"a":"recall","vg":"bacterio1-bordetella:e2/recall/1"},"1k8f201":{"a":"recall","vg":"bacterio1-bordetella:e5/recall/1"},"1quys3e":{"a":"recall","vg":"bacterio1-bordetella:e5/recall/2"},"l7c1y4":{"a":"recall","vg":"bacterio1-bordetella:e6/recall/1"},"ox11yk":{"a":"recall","vg":"bacterio1-bordetella:e6/recall/2"},"1aabnic":{"a":"recall","vg":"bacterio1-bordetella:e7/recall/1"},"1yoy7nd":{"a":"recall","vg":"bacterio1-bordetella:e8/recall/1"},"102fl6o":{"a":"recall","vg":"bacterio1-bordetella:e8/recall/2"},"1k9hkg7":{"a":"recall","vg":"bacterio1-bordetella:e9/recall/1"}},"explRev":"fcdd388f4289"};
